// Count UNS events per event type and detect gaps in the event sequence number.
// msg.topic = vf/plant01/final-assembly/line01/{device}/event/{event}
// msg.payload = parsed JSON (the mqtt-in node is set to "a parsed JSON object")

if (msg.payload === true) {                 // from the "reset counters" inject node
    context.set("counts", {});
    node.status({});
    return null;
}

const levels = msg.topic.split("/");
const device = levels[4];                   // e.g. "plc01"
const type = levels[6] || msg.payload.event; // e.g. "part_inspected"

// node context survives between messages (but not a restart of Node-RED)
const counts = context.get("counts") || {};
counts[type] = (counts[type] || 0) + 1;
context.set("counts", counts);

// seq counts all events of one factory session; a jump > 1 means lost events
const last = context.get("last") || {};
if (last.session === msg.payload.session && msg.payload.seq > last.seq + 1) {
    node.warn(`events lost: seq ${last.seq} -> ${msg.payload.seq}`);
}
context.set("last", { session: msg.payload.session, seq: msg.payload.seq });

const total = Object.values(counts).reduce((a, b) => a + b, 0);
node.status({ fill: "green", shape: "dot", text: `${total} events, last: ${device}/${type}` });

msg.payload = counts;                       // e.g. {"part_released": 12, "part_inspected": 11, ...}
return msg;

// Sliding-window reject counter. Change the parameters, then press Deploy.
const WINDOW_S = 60;   // window length in seconds
const LIMIT = 3;       // alert when MORE than LIMIT rejects lie inside the window

// Time base: the event timestamp (simulation time base), fallback wall clock
const t = Date.parse(msg.payload.ts) || Date.now();

// keep only rejects that are still inside the window, then add the new one
const rejects = (context.get("rejects") || []).filter(x => x > t - WINDOW_S * 1000 && x <= t);
rejects.push(t);
context.set("rejects", rejects);

const alarm = rejects.length > LIMIT;
node.status({ fill: alarm ? "red" : "green", shape: "dot", text: `${rejects.length} rejects / ${WINDOW_S} s` });
if (!alarm) return null;

// debounce: at most one alert per window
if (t - (context.get("lastAlert") || 0) < WINDOW_S * 1000) return null;
context.set("lastAlert", t);

msg.payload = {
    alert: "reject_rate",
    rejects: rejects.length,
    window_s: WINDOW_S,
    limit: LIMIT,
    last_serial: msg.payload.serial,
    ts: new Date(t).toISOString(),
    source: "nodered-sandbox"
};
return msg;               // the mqtt-out node serialises the object to JSON

// AAS API: identifiers in the path are base64url-encoded (no padding).
const SUBMODEL_ID = "https://virtual-factory.example/ids/sm/PLC01/OperationalData/1";
const AAS_URL = "http://aas-env:8091";   // compose service name; from the host: http://localhost:8091

const encoded = Buffer.from(SUBMODEL_ID, "utf8").toString("base64url");
// encoded = "aHR0cHM6Ly92aXJ0dWFsLWZhY3RvcnkuZXhhbXBsZS9pZHMvc20vUExDMDEvT3BlcmF0aW9uYWxEYXRhLzE"

msg.url = `${AAS_URL}/submodels/${encoded}/$value`;   // used by the http request node (its URL is empty)
return msg;

// msg.statusCode comes from the http request node
if (msg.statusCode !== 200) {
    node.status({ fill: "red", shape: "ring", text: `HTTP ${msg.statusCode}` });
    node.warn(msg.payload);
    return null;
}
const pv = msg.payload.ProcessValues || {};   // PLC process image (SubmodelElementCollection)

// ValueOnly ($value) serialises every value as a string ("12"), so convert explicitly
msg.payload = {
    parts_total: Number(pv.parts_total),
    parts_ok: Number(pv.parts_ok),
    parts_nok: Number(pv.parts_nok),
    packml_state: Number(pv.packml_state),
    operating_state: msg.payload.OperatingState
};
node.status({ fill: "green", shape: "dot",
    text: `${msg.payload.parts_total} total, ${msg.payload.parts_ok} OK, ${msg.payload.parts_nok} NOK` });
return msg;

// Synchronous invocation of an AAS operation (AAS API part 2, POST .../invoke)
const SUBMODEL_ID = "https://virtual-factory.example/ids/sm/LINE01/LineControl/1";
const encoded = Buffer.from(SUBMODEL_ID, "utf8").toString("base64url");

msg.command = msg.payload;              // "Hold" / "Unhold" from the inject node, kept for the result
msg.url = `http://aas-env:8091/submodels/${encoded}/submodel-elements/ExecutePackMLCommand/invoke`;
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    inputArguments: [
        { value: { modelType: "Property", idShort: "Command", valueType: "xs:string", value: msg.command } }
    ],
    clientTimeoutDuration: "PT15S"      // ISO 8601 duration
};
return msg;

if (msg.statusCode !== 200) {
    node.status({ fill: "red", shape: "ring", text: `HTTP ${msg.statusCode}` });
    node.warn(msg.payload);
    return null;
}
// outputArguments: [{value: {idShort: "Accepted", value: "true", ...}}, {value: {idShort: "State", ...}}, ...]
const out = {};
for (const arg of msg.payload.outputArguments || []) {
    out[arg.value.idShort] = arg.value.value;
}
const accepted = out.Accepted === "true";
node.status({ fill: accepted ? "green" : "yellow", shape: "dot", text: `${msg.command}: ${out.State}` });

msg.payload = {
    command: msg.command,
    executionState: msg.payload.executionState,   // Completed / Failed / Timeout ...
    accepted: accepted,
    state: out.State,
    message: out.Message
};
return msg;
